      const chunk = Array.isArray(next) ? next : [];
      if (chunk.length === 0) {
        setJobsHasMore(false);
      } else {
        setJobs((prev) => [...(prev || []), ...chunk]);
        setJobsHasMore(chunk.length >= _P37_JOBS_PAGE);
