    if (deleteBusyMode) return;                    // guard double-click
    setDeleteBusyMode(mode);
    try {
      const res = await api.del(`/customers/${id}?mode=${mode}`);
      const verb = mode === "hard" ? "permanently deleted" : "soft-deleted";
      setToast({
        tone: "success",
        message: res?.already_deleted
